<script>
    const womanSlider = new Swiper("#swiperSlider", {
        loop: true,
        speed: 700,

        slidesPerView: 6,

        autoplay: {
            delay: 2500,
            disableOnInteraction: false,
            pauseOnMouseEnter: false,
        },

        navigation: {
            nextEl: "#swiperSlider .swiper-button-next",
            prevEl: "#swiperSlider .swiper-button-prev",
        },

        breakpoints: {
            320: {
                slidesPerView: 2,
            },

            576: {
                slidesPerView: 2,
            },

            768: {
                slidesPerView: 3,
            },

            992: {
                slidesPerView: 4,
            },

            1200: {
                slidesPerView: 6,
            }
        }
    });
</script>

<script>
    const data = {
        skills: [
            "React JS Developer",
            "Node.js Developer",
            "Python Developer",
            "UI/UX Designer",
            "Digital Marketing",
            "Content Writer",
            "Data Analyst",
            "Graphic Designer",
            "Java Developer",
            "Product Manager",
            "HR Executive",
            "Sales Executive",
            "Google",
            "Amazon",
            "Microsoft",
            "TCS",
            "Infosys"
        ],

        location: [
            "Delhi",
            "Mumbai",
            "Bangalore",
            "Hyderabad",
            "Pune",
            "Chennai",
            "Kolkata",
            "Ahmedabad",
            "Noida",
            "Gurgaon",
            "Remote"
        ],

        experience: [
            "Fresher",
            "0-1 years",
            "1-3 years",
            "3-5 years",
            "5-8 years",
            "8+ years"
        ]
    };

    document.querySelectorAll('.field').forEach(field => {
        const key = field.dataset.field;
        const input = field.querySelector('input');
        const box = field.querySelector('.suggestions');

        let activeIndex = -1;

        function renderList(items, query) {
            box.innerHTML = "";

            if (items.length === 0) {
                box.innerHTML = `
                    <div class="suggestion-empty">
                        No matches found
                    </div>
                `;

                box.classList.add('show');
                return;
            }

            items.forEach((item) => {
                const div = document.createElement('div');

                div.className = 'suggestion-item';

                let highlighted = item;

                if (query) {
                    const escapedQuery = query.replace(
                        /[.*+?^${}()|[\]\\]/g,
                        '\\$&'
                    );

                    highlighted = item.replace(
                        new RegExp(`(${escapedQuery})`, 'gi'),
                        '<mark>$1</mark>'
                    );
                }

                div.innerHTML = `
                    <span>${highlighted}</span>
                `;

                div.addEventListener('mousedown', (e) => {
                    e.preventDefault();

                    input.value = item;

                    box.classList.remove('show');

                    activeIndex = -1;
                });

                box.appendChild(div);
            });

            box.classList.add('show');
        }

        function showAll() {
            renderList(data[key], "");
        }

        function filter(query) {
            const value = query.trim().toLowerCase();

            if (!value) {
                showAll();
                return;
            }

            const matches = data[key].filter(item =>
                item.toLowerCase().includes(value)
            );

            renderList(matches, query);
        }

        // Focus - show all suggestions
        input.addEventListener('focus', () => {
            filter(input.value);
        });

        // Search while typing
        input.addEventListener('input', () => {
            activeIndex = -1;
            filter(input.value);
        });

        // Keyboard navigation
        input.addEventListener('keydown', (e) => {
            const items = box.querySelectorAll('.suggestion-item');

            if (!items.length) return;

            if (e.key === 'ArrowDown') {
                e.preventDefault();

                activeIndex =
                    (activeIndex + 1) % items.length;

            } else if (e.key === 'ArrowUp') {
                e.preventDefault();

                activeIndex =
                    (activeIndex - 1 + items.length) %
                    items.length;

            } else if (e.key === 'Enter') {

                if (activeIndex >= 0) {
                    e.preventDefault();

                    input.value =
                        items[activeIndex].textContent.trim();

                    box.classList.remove('show');

                    activeIndex = -1;
                }

                return;

            } else {
                return;
            }

            items.forEach(item => {
                item.classList.remove('highlighted');
            });

            items[activeIndex].classList.add('highlighted');

            items[activeIndex].scrollIntoView({
                block: 'nearest'
            });
        });

        // Close dropdown when clicking outside
        document.addEventListener('click', (e) => {
            if (!field.contains(e.target)) {
                box.classList.remove('show');
                activeIndex = -1;
            }
        });
    });
</script>

<script>
  // Only one FAQ open at a time across BOTH columns (left + right combined).
  const allCollapses = Array.from(document.querySelectorAll('.faq-item .collapse'));

  allCollapses.forEach(collapseEl => {
    const item = collapseEl.closest('.faq-item');

    collapseEl.addEventListener('show.bs.collapse', () => {
      // close every other open accordion item on the page (both columns)
      allCollapses.forEach(other => {
        if (other !== collapseEl) {
          bootstrap.Collapse.getOrCreateInstance(other, { toggle: false }).hide();
        }
      });
      item.classList.add('active');
    });

    collapseEl.addEventListener('hide.bs.collapse', () => {
      item.classList.remove('active');
    });
  });
</script>

